<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableEnabledVO;

trait TemplateVariableEnabledAccessor
{
    private ?TemplateVariableEnabledVO $_enabled = null;
    public function isEnabled(): ?bool
    {
        return $this->_enabled?->value();
    }
    public function enabled(): ?TemplateVariableEnabledVO
    {
        return $this->_enabled;
    }
    public function isEnabledChanged(?self $original = null): bool
    {
        return null !== $this->_enabled && !$this->_enabled->equals($original?->_enabled);
    }
    public function withEnabled(TemplateVariableEnabledVO|bool|null $enabled): self
    {
        $copy = clone $this;
        $copy->_enabled = TemplateVariableEnabledVO::from($enabled);
        return $copy;
    }
}
